			// Race Condition handled by atomic.AddInt32 in results consumer
			// Workers block here if no one reads 'results'
			results <- Result{JobID: job.ID, Val: job.ID * 2}
		}
	}(i)
}

// Start a goroutine to consume results concurrently
resultWg.Add(1)
go func() {
	defer resultWg.Done()
	for range results {
		atomic.AddInt32(&processedCount, 1)
	}
}()

	// Wait for all jobs to be sent and workers to process them
	workerWg.Wait()

	// Close the results channel AFTER all workers are done sending results
	close(results)

	// Wait for all results to be consumed
	resultWg.Wait()

	return int(processedCount.Load()), nil
}

